def bt_dang16_p3_b3_c1_hh12(self):
    # Random tọa độ điểm A(a,b,c) và vector v(m,n,p)
    while True:
        a = random.randint(-10, 10)
        b = random.randint(-10, 10)
        c = random.randint(-10, 10)
        if a == 0 and b == 0 and c == 0:
            continue

        m = random.randint(-5, 5)
        n = random.randint(-5, 5)
        p = random.randint(-5, 5)
        if m == 0 and n == 0 and p == 0:
            continue

        # Các hệ số của tam thức bậc 2: C*u^2 + B*u + A_val
        A_val = m**2 + n**2 + p**2
        B_val = 2 * (a*m + b*n + c*p)
        C_val = a**2 + b**2 + c**2

        # Điều kiện để hàm số đạt GTNN tại u > 0 (tức t > 0)
        if B_val < 0:
            min_v0_sq = A_val - (B_val**2) / (4 * C_val)
            if min_v0_sq > 0:
                min_v0 = math.sqrt(min_v0_sq)
                kq_exact = Decimal(str(min_v0)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                kq = str(kq_exact).replace('.', ',')
                break

    # Hàm hỗ trợ định dạng dấu cộng/trừ trong phương trình
    def fmt(val, is_first=False):
        if is_first:
            return str(val)
        return f"+ {val}" if val >= 0 else f"- {abs(val)}"

    # Các đáp án trắc nghiệm
    da = f'${kq}$'

