    # Sử dụng set để đảm bảo các đáp án không bị trùng nhau
    tap_dap_an_sai = set()
    while len(tap_dap_an_sai) < 3:
        offset = random.choice([-0.03, -0.02, -0.01, 0.01, 0.02, 0.03])
        sai_val = float(kq_exact) + offset
        if sai_val > 0:
            sai_dec = Decimal(str(sai_val)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            sai_str = f"${str(sai_dec).replace('.', ',')}$"
            if sai_str != da:
                tap_dap_an_sai.add(sai_str)

    s = list(tap_dap_an_sai)
    das1 = s[0]
    das2 = s[1]
