    # Các đáp án
    da_d = ('\\True ' + str(da))
    da_s1 = str(das1)
    da_s2 = str(das2) 
    da_s3 = str(das3) 

    # Đưa các đáp án vào 1 danh sách chọn ngẫu nhiên
    list_1 = [da_d, da_s1, da_s2, da_s3]
    random.shuffle(list_1)

    # Tính toán các thông số cho lời giải
    B_str = fmt(B_val)
    u_min_val = -B_val / (2 * C_val)
    u_min_frac = latex(Rational(-B_val, 2 * C_val))
    min_v0_sq_frac = latex(Rational(A_val * 4 * C_val - B_val**2, 4 * C_val))

    # Nội dung lời giải
    loigiai = ('''Giả sử tại thời điểm $t > 0$ (giây), con cá ở vị trí $M$. \\\\
               Khi đó $\\overrightarrow{AM} = t\\vec{v} = (%st; %st; %st) \\Rightarrow M(%s %s t; %s %s t; %s %s t)$.\\\\
    Để con tàu gặp được con cá thì quãng đường con tàu đi được phải bằng $OM$, tức là:\\\\
    $v_0 t = OM = \\sqrt{(%s %s t)^2 + (%s %s t)^2 + (%s %s t)^2}$\\\\
    $\\Rightarrow v_0^2 = \\frac{%s t^2 %s t + %s}{t^2} = %s \\frac{1}{t^2} %s \\frac{1}{t} + %s$.\\\\
    Đặt $u = \\frac{1}{t} > 0$, ta có hàm số $f(u) = %s u^2 %s u + %s$. \\\\
    Hàm số $f(u)$ đạt giá trị nhỏ nhất tại $u = \\frac{%s}{2 \\cdot %s} = %s$.\\\\
    Khi đó $\\min f(u) = %s \\Rightarrow \\min v_0 = \\sqrt{%s} \\approx %s$.'''
               % (
                   m, n, p, 
                   a, fmt(m), b, fmt(n), c, fmt(p),
                   a, fmt(m), b, fmt(n), c, fmt(p),
                   A_val, B_str, C_val, 
                   C_val, B_str, A_val,
                   C_val, B_str, A_val,
                   -B_val, C_val, u_min_frac,
                   min_v0_sq_frac, min_v0_sq_frac, kq
               ))
    dapan='\\shortans[0]{$%s$}\n'%(kq)
    # B2: Xuất câu trắc nghiệm y hệt theo format
    content = ('\\begin{minipage}{\\textwidth} \n'
               '\\begin{ex}\n' + str(noidungcauhoi) + dapan+
               '\\loigiai{\n' + str(loigiai) + '\n}\n'
               '\\end{ex}\n\\end{minipage} \n\n')
    return content

